        ["sql-formatter"] = S("SQL formatter and beautifier",
            "Make long, single-line SQL queries readable. This SQL beautifier puts each clause (SELECT, FROM, JOIN, WHERE, GROUP BY, HAVING, ORDER BY) on its own line, indents subqueries, CTEs and CASE expressions, aligns conditions under WHERE and AND, and can uppercase keywords. It works with SQL Server (T-SQL), PostgreSQL, MySQL, SQLite, Oracle and Snowflake syntax, and is handy for tidying queries copied from logs, ORMs such as Entity Framework, Hibernate or Dapper, or stored-procedure dumps before a code review.",
            ["Paste your SQL query, stored procedure or ORM-generated statement.", "Choose indent size (2 or 4 spaces) and whether keywords should be uppercased.", "Click Format and copy the result, or Minify to collapse it back to one line."],
            "select u.id,u.name,count(o.id) from users u left join orders o on o.user_id=u.id where u.active=1 group by u.id,u.name order by 3 desc\n\u2192\nSELECT u.id, u.name, COUNT(o.id)\nFROM users u\nLEFT JOIN orders o ON o.user_id = u.id\nWHERE u.active = 1\nGROUP BY u.id, u.name\nORDER BY 3 DESC",
            new Faq("Which SQL dialects are supported?", "The formatter is dialect-agnostic and handles standard SQL plus common syntax from T-SQL, PostgreSQL, MySQL and Oracle, including [bracketed], `backticked` and \"double-quoted\" identifiers, TOP and LIMIT, CTEs (WITH), window functions and MERGE statements."),
            new Faq("Will it change my query logic?", "No. Only whitespace and keyword casing change; string literals, comments, identifiers and parameter names (@p0, :id, ?) are preserved exactly, so the formatted query returns identical results."),
