        ["json-path"] = S("JSONPath tester",
            "Evaluate JSONPath expressions against your JSON and see the matching values instantly. JSONPath is to JSON what XPath is to XML: a query language for selecting values inside a document. It is used in Postman tests, Kubernetes (kubectl -o jsonpath), AWS Step Functions and EventBridge, Azure Logic Apps, Spring, Jayway, Newtonsoft.Json SelectToken, jq-style pipelines and many API gateways. Use this tester to prototype an expression before putting it in code, or to pull a single value out of a large API response.",
            ["Paste your JSON document.", "Enter a JSONPath expression such as $.store.book[*].author or $..price.", "View the matched values and their count as you type."],
            "$.store.book[?(@.price < 10)].title  →  titles of all books cheaper than 10\n$..author                             →  every author at any depth\n$.store.book[0]                       →  the first book\n$.store.book[-1:]                     →  the last book\n$.store.book[*].isbn                  →  all ISBNs (missing ones skipped)",
            new Faq("What is the JSONPath syntax?", "$ is the root, . or [''] selects a child, [n] selects an array index, [*] selects all elements, .. descends recursively, [start:end] slices an array and [?(expr)] filters elements using @ as the current item. For example $.users[?(@.age > 30)].name returns the names of all users older than 30."),
            new Faq("What does $.. mean?", "The recursive descent operator searches for the property at every depth of the document. $..id returns every id field anywhere, no matter how deeply nested."),
            new Faq("How do I filter an array with JSONPath?", "Use a filter expression in square brackets: $.items[?(@.status == 'active')] keeps only items whose status is active. Comparisons (==, !=, <, >, <=, >=), logical && and ||, and regex matching with =~ are supported."),
            new Faq("How do I get the last element of an array?", "Use a negative slice: $.items[-1:] returns the last element, $.items[-2:] the last two. $.items[0] returns the first element."),
            new Faq("How do I select a key that contains a dot or a space?", "Use bracket notation with quotes: $['my.key'] or $.data['first name']. Dot notation only works for simple identifiers."),
            new Faq("What is the difference between JSONPath and jq?", "JSONPath is a selection language: it returns the values that match a path. jq is a full transformation language with functions, arithmetic and output shaping. If you only need to extract values, JSONPath is simpler and is supported natively in far more products."),
            new Faq("Why does my expression return nothing?", "The most common causes are a missing $ at the start, a case mismatch in a property name (JSONPath is case-sensitive), using dot notation on a key with special characters, or quoting the whole expression. Check the matched count shown under the input while you type.")),

        ["base64"] = S("Base64 encoder and decoder",
