        ["image-to-base64"] = S("image to Base64 converter",
            "Convert images (PNG, JPG, GIF, SVG, WebP, BMP, ICO) into Base64 data URLs that can be embedded directly in HTML, CSS, JSON, Markdown or email without a separate file request. The output is a string of the form data:image/png;base64,iVBORw0KGgo... which browsers render exactly like an image file. Typical uses are inlining small icons and logos in a single-file HTML page, email signatures, CSS background images, favicons, JSON API payloads and test fixtures.",
            ["Drop an image or choose a file (nothing is uploaded; it is read locally in your browser).", "Pick the output format: raw Base64, data URL, HTML img tag or CSS background-image.", "Copy the snippet into your code."],
            "logo.png (2 KB)  →  <img src=\"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAA...\" alt=\"logo\">\nicon.svg  →  background-image: url(\"data:image/svg+xml;base64,PHN2ZyB4bWxucz0i...\");",
            new Faq("When should I inline images as Base64?", "For small icons and images under a few kilobytes, single-file HTML documents, email templates and places where you cannot host a separate file. Larger images are better served as separate cached files because Base64 adds about 33 % to the size and cannot be cached independently."),
            new Faq("How do I use a Base64 image in HTML?", "Put the data URL in the src attribute: <img src=\"data:image/png;base64,....\" alt=\"\">. Choose the HTML img tag output and the tag is generated for you."),
            new Faq("How do I use a Base64 image in CSS?", "Use it as a background: .logo { background-image: url(\"data:image/png;base64,....\"); }. The CSS output option produces the complete rule."),
            new Faq("Does Base64 make the image bigger?", "Yes, by roughly 33 % (every 3 bytes become 4 characters). Gzip or Brotli compression on your server recovers most of that, but the image can no longer be cached separately from the page."),
            new Faq("Can I convert SVG to Base64?", "Yes. SVG files become data:image/svg+xml;base64,... which works in img tags and CSS. For SVG you can also URL-encode the markup instead of Base64, which is slightly smaller."),
