        ["color-contrast-checker"] = S("color contrast checker",
            "Check whether your text and background colors are readable for everyone. The checker calculates the WCAG 2.x contrast ratio and shows pass or fail for AA and AAA, for normal text, large text and UI components, with a live preview. If a combination fails, it suggests the nearest accessible text color.",
