        ["crypto-tools"] = S("bcrypt, AES and RSA tool",
            "Hash passwords with bcrypt and verify them against existing hashes, encrypt and decrypt text with AES-256-GCM using a password, or generate RSA key pairs and encrypt with RSA-OAEP. All cryptography runs locally using the browser's Web Crypto API and a managed bcrypt implementation, so nothing is uploaded.",
            ["Choose Bcrypt, AES or RSA.", "Enter your text, password or key.", "Copy the hash, ciphertext or PEM keys."],
            "bcrypt(\"secret\", cost 10)  →  $2a$10$…",
            new Faq("What bcrypt cost should I use?", "A cost of 10–12 is common in production. Each +1 doubles the time it takes to compute a hash."),
            new Faq("Can bcrypt hashes be decrypted?", "No. Bcrypt is a one-way hash. You can only verify whether a password matches a hash."),
            new Faq("How is the AES key derived from my password?", "PBKDF2 with SHA-256 and a random 16-byte salt derives a 256-bit key. The salt and IV are stored at the start of the output.")),

        ["connection-string-builder"] = S("connection string builder",
            "Build correct connection strings for SQL Server, PostgreSQL (Npgsql), MySQL, SQLite, MongoDB and Redis (StackExchange.Redis) without looking up the keyword names. You also get a ready-to-paste appsettings.json section and an environment variable using the ConnectionStrings__Name convention used by ASP.NET Core.",
