            new Faq("How do I override a connection string in Docker or Azure?", "Set an environment variable named ConnectionStrings__DefaultConnection. ASP.NET Core maps the double underscore to the : separator.")),

        ["flexbox-grid-playground"] = S("Flexbox and CSS Grid playground",
            "Learn and prototype CSS layouts by changing Flexbox and Grid properties and watching the result instantly. Adjust direction, wrapping, justify-content, align-items, grid-template-columns, auto-flow and gap, then copy the generated CSS.",
