        ["dockerfile-generator"] = S("Dockerfile and GitHub Actions generator",
            "Generate a production-ready multi-stage Dockerfile for .NET, Node.js or Python that runs as a non-root user, a matching .dockerignore, and a GitHub Actions CI workflow that restores, builds and tests your code and can push a container image to GitHub Container Registry.",
            ["Choose your stack and version.", "Set the port, project name or start command.", "Copy the Dockerfile, .dockerignore and .github/workflows/ci.yml."],
