        ["sql-murder-mystery"] = S("SQL murder mystery game",
            "Practice SQL by solving a crime. Query tables of crime scene reports, people, driver's licenses, interviews and gym check-ins with SELECT, JOIN, WHERE and LIKE to follow the clues and find the killer. A real SQLite database runs in your browser.",
