        ["big-o-quiz"] = S("Big-O notation quiz",
            "Practice time complexity analysis for coding interviews. Each question shows a short code snippet and asks for its Big-O complexity, from O(1) and O(log n) to O(n log n), O(n²) and O(2ⁿ), with an explanation after every answer.",
            ["Read the code snippet.", "Pick its time complexity.", "Read the explanation and continue."],
            "for (i = 1; i < n; i *= 2)  →  O(log n)",
