            new Faq("What is the complexity of a hash map lookup?", "O(1) on average, O(n) in the worst case when many keys collide.")),

        ["vim-trainer"] = S("Vim tutorial game",
            "Learn Vim by doing. Each level gives you text and a target; edit it using normal and insert mode commands such as w, b, dd, dw, cw, ciw, f, t, di(, yy, p and u. Your keystrokes are counted against par, and progress is saved in your browser.",
