        ["guess-the-language"] = S("guess the programming language quiz",
            "How well do you know programming languages? Look at a short code snippet and identify the language: Rust, Go, Kotlin, Swift, Elixir, Haskell, F#, Scala, Lua, Dart and more. Each answer explains the giveaway syntax.",
