        ["regex-golf"] = S("regex golf game",
            "Regex golf is a puzzle where you write the shortest regular expression that matches every string in one list and none in the other. It is a fun way to practise character classes, anchors, alternation, quantifiers and lookarounds, with your score tracked by pattern length.",
            ["Read the match and no-match lists.", "Type a regex; matches update live.", "Shorten the pattern to lower your score."],
            "Match: foo, food, fool · Avoid: bar, baz  →  ^f",
            new Faq("Which regex flavour is used?", "JavaScript regular expressions, which support lookahead, lookbehind, named groups and Unicode classes."),
            new Faq("Does a shorter regex always win?", "Yes, as long as it matches all required strings and none of the excluded ones.")),

        ["http-status-quiz"] = S("HTTP status code quiz",
            "Test your knowledge of HTTP response codes from 100 Continue to 511 Network Authentication Required. Each question shows a status code or a scenario and asks what it means, with an explanation that helps you remember 301 vs 302, 401 vs 403 and 502 vs 504.",
            ["Read the status code or scenario.", "Choose the correct meaning.", "Read the explanation and continue."],
            "A request needs valid credentials  →  401 Unauthorized",
            new Faq("What is the difference between 401 and 403?", "401 means authentication is missing or invalid; 403 means the client is authenticated but not allowed to access the resource."),
            new Faq("When should an API return 422 instead of 400?", "422 Unprocessable Content is used when the request is well-formed but fails validation; 400 is for malformed syntax.")),

        ["binary-hex-game"] = S("binary and hexadecimal conversion game",
            "Build fluency converting between binary, decimal and hexadecimal under time pressure. The game shows a number in one base and asks for it in another, which trains the mental shortcuts developers use for bit masks, colour codes, memory addresses and network masks.",
            ["Choose a difficulty.", "Convert each number before the timer runs out.", "Check your streak and try again."],
            "0b1010 1111  →  0xAF  →  175",
            new Faq("What is the fastest way to convert binary to hex?", "Group the bits in fours from the right; each group maps to one hex digit (1111 = F, 1010 = A)."),
            new Faq("Why do programmers use hexadecimal?", "One hex digit represents exactly four bits, so bytes and memory addresses are shorter and easier to read than binary.")),

        ["bitwise-puzzle"] = S("bitwise operations puzzle",
            "Practise AND, OR, XOR, NOT and bit shifts by reaching a target value from a starting number in as few operations as possible. Each move shows the binary result, making it easy to see how flags, masks and shifts change individual bits.",
            ["Read the start and target values.", "Apply bitwise operations to transform the number.", "Reach the target in the fewest moves."],
            "5 (0101) XOR 3 (0011)  →  6 (0110)",
            new Faq("What does XOR do?", "XOR sets a bit to 1 when exactly one of the two input bits is 1. XOR with the same value twice returns the original."),
            new Faq("What is a left shift equivalent to?", "Shifting left by n multiplies by 2ⁿ; shifting right by n divides by 2ⁿ and discards the remainder.")),

        ["code-wordle"] = S("programming Wordle game",
