        ["keyboard-shortcut-trainer"] = S("keyboard shortcut trainer",
            "Learn Visual Studio and VS Code keyboard shortcuts through repetition. The trainer names an action such as Go to Definition, Rename Symbol or Toggle Comment and you press the real key combination. Correct answers are repeated less often so you focus on the ones you miss.",
