        ["css-selector-game"] = S("CSS selector game",
            "Learn CSS selectors by writing a selector that targets exactly the highlighted elements. Levels progress from element and class selectors through child, sibling and attribute selectors to pseudo-classes like :nth-child, :not and :has.",
            ["Look at the highlighted elements and the HTML.", "Type a selector that matches only those elements.", "Pass the level and move on to the next."],
