            new Faq("What is the difference between > and a space?", "A space matches any descendant; > matches only direct children."),
            new Faq("Is :has supported?", "Yes. :has() lets you select a parent based on its children and is supported in all modern browsers.")),

        ["git-command-quiz"] = S("Git command quiz",
            "Sharpen your Git skills with scenario-based questions. Each one describes a real situation, such as undoing the last commit, moving uncommitted changes to a new branch or rewriting history before a pull request, and asks which Git command solves it.",
            ["Read the scenario.", "Pick the Git command that solves it.", "Read the explanation of what the command does."],
            "Undo the last commit but keep the changes staged  →  git reset --soft HEAD~1",
            new Faq("What is the difference between git merge and git rebase?", "Merge creates a merge commit joining two histories; rebase replays your commits on top of another branch for a linear history."),
            new Faq("How do I recover a deleted branch?", "Use git reflog to find the last commit of the branch and then git checkout -b branch-name <sha>.")),

        ["what-is-my-ip"] = new("what is my IP address tool",
            "Find your public IPv4 and IPv6 address along with approximate location, ISP and ASN. Your public IP is the address websites see when you connect, which is different from the private 192.168.x.x or 10.x.x.x address assigned by your router. Useful for configuring firewalls, allow-lists, VPN checks and remote access.",
