        ["uptime-monitor"] = new("website uptime and SSL checker",
            "Check whether a website is up, how fast it responds and when its SSL certificate expires. Requests are made from several regions so you can tell a global outage from a regional one, and the certificate chain is inspected for expiry and common misconfigurations.",
